VRT_L("tle-c-svt-r12",{"duree":20,"titre":"Monohybridisme avec dominance","accroche":"Les lois de Mendel à partir d'un seul caractère.","intro":"Un croisement entre lignées pures permet de déduire le mode de transmission d'un caractère.","objectifs":["définir les termes","établir un échiquier","analyser un test-cross"],"parties":[{"t":"Vocabulaire","html":"<div class='def'><b>Définition</b>Le <strong>monohybridisme</strong> étudie la transmission d'un seul caractère. Un allèle <strong>dominant</strong> s'exprime chez l'hétérozygote, l'allèle <strong>récessif</strong> y est masqué.</div>"},{"t":"Résultats","verrou":true},{"t":"Test-cross","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":12,"apc":{"module":"Génétique et reproduction","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques","situation":"Un éleveur de porcs de Bafia remarque des naissances à longue et courte queue dans une même portée.","tache":"Propose une démarche pour comprendre ce résultat."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r13",{"duree":20,"titre":"Le dihybridisme","accroche":"Deux caractères, seize cases.","intro":"Le dihybridisme étudie la transmission simultanée de deux caractères.","objectifs":["établir un échiquier","reconnaître 9-3-3-1","interpréter un test-cross"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>dihybridisme</strong> étudie la transmission de deux caractères. Pour des gènes indépendants, on obtient en F₂ les proportions <strong>9/16 - 3/16 - 3/16 - 1/16</strong>.</div>"},{"t":"Test-cross","verrou":true},{"t":"Interprétation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":13,"apc":{"module":"Génétique et reproduction","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques","situation":"Un agronome de l'Ouest croise deux variétés de maïs différant par deux caractères.","tache":"Dis quels résultats attendre en F₂ si les gènes sont indépendants."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r14",{"duree":20,"titre":"Le brassage intrachromosomique","accroche":"Des gènes liés peuvent se séparer.","intro":"Si les gènes sont portés par le même chromosome, les proportions diffèrent.","objectifs":["reconnaître des gènes liés","calculer un pourcentage de recombinaison","expliquer le crossing-over"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Des <strong>gènes liés</strong> sont portés par le même chromosome. Le <strong>crossing-over</strong> produit des gamètes recombinés.</div>"},{"t":"Test-cross","verrou":true},{"t":"Interprétation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":14,"apc":{"module":"Génétique et reproduction","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques","situation":"Dans une expérience de génétique, un test-cross donne deux phénotypes parentaux à 45 % chacun et deux recombinés à 5 % chacun.","tache":"Conclus."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r15",{"duree":20,"titre":"Transmissions autosomiques","accroche":"Albinisme, drépanocytose, achondroplasie.","intro":"Certaines maladies se transmettent par des gènes portés par des autosomes.","objectifs":["reconnaître le mode de transmission","écrire les génotypes","calculer un risque"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Une transmission <strong>autosomique</strong> concerne un gène porté par un chromosome non sexuel. Elle est récessive ou dominante.</div>"},{"t":"Exemples","verrou":true},{"t":"Risque","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":15,"apc":{"module":"Génétique et reproduction","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques","situation":"Dans une campagne à Douala sur la drépanocytose (allèle S récessif), on présente quatre couples : AA × AS ; AS × AS ; AS × SS ; AA × SS.","tache":"Calcule pour chaque couple le risque d'enfant SS et dis quelles unions présenter comme à risque."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r16",{"duree":20,"titre":"Transmissions gonosomiques","accroche":"Daltonisme et hémophilie touchent surtout les garçons.","intro":"Une maladie portée par X s'exprime plus souvent chez l'homme.","objectifs":["reconnaître une transmission liée à X","calculer un risque","expliquer le rôle de la mère"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une transmission <strong>gonosomique récessive</strong> liée à X touche davantage les hommes, qui ne possèdent qu'un chromosome X.</div>"},{"t":"Exemples","verrou":true},{"t":"Risque","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":16,"apc":{"module":"Génétique et reproduction","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques","situation":"Une famille de Yaoundé a plusieurs garçons hémophiles et aucune fille atteinte.","tache":"Explique cette répartition."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r17",{"duree":20,"titre":"Intégration : limiter les maladies génétiques","accroche":"Causerie, échiquier, affiche et slogan.","intro":"Le bac demande de passer de la connaissance à l'action de sensibilisation.","objectifs":["préparer une causerie","présenter des échiquiers","rédiger un slogan"],"parties":[{"t":"Compétence","html":"<div class='def'><b>Définition</b><strong>Limiter la fréquence d'une maladie génétique</strong>, c'est informer, dépister et conseiller les familles.</div>"},{"t":"La causerie","verrou":true},{"t":"Affiche et slogan","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":17,"apc":{"module":"Génétique et reproduction","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques","situation":"Le couple X a cinq enfants drépanocytaires, alors que les parents se disent en bonne santé. Un médecin te sollicite pour une campagne.","tache":"Présente un texte de causerie et un slogan."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r06",{"duree":20,"titre":"Acides nucléiques et duplication de l'ADN","accroche":"Deux mètres d'ADN recopiés dans chaque cellule.","intro":"L'ADN porte l'information génétique. Sa structure explique sa copie fidèle avant chaque division.","objectifs":["décrire l'ADN et l'ARN","appliquer la complémentarité des bases","expliquer la réplication semi-conservative"],"parties":[{"t":"La structure de l'ADN","html":"<div class='def'><b>Définition</b>L'<strong>ADN</strong> est une double hélice de nucléotides. Chaque nucléotide comprend un phosphate, un désoxyribose et une base : A, T, C ou G.</div>"},{"t":"Complémentarité et ARN","verrou":true},{"t":"La réplication","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":6,"apc":{"module":"Génétique et reproduction","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques","situation":"Pour un TP au lycée de Mutengene, les élèves construisent une maquette d'ADN avec des pailles et des capsules colorées.","tache":"Indique les règles à respecter."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r07",{"duree":20,"titre":"Biosynthèse des protéines","accroche":"Du gène au caractère.","intro":"Un gène commande la fabrication d'une protéine qui détermine un caractère.","objectifs":["décrire transcription et traduction","utiliser le code génétique","relier protéine et caractère"],"parties":[{"t":"Du gène à la protéine","html":"<div class='def'><b>Définition</b>La <strong>transcription</strong> copie un gène en ARN messager dans le noyau. La <strong>traduction</strong> assemble les acides aminés au niveau des ribosomes.</div>"},{"t":"Le code génétique","verrou":true},{"t":"Protéine et caractère","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":7,"apc":{"module":"Génétique et reproduction","famille":"Choix et observation de saines habitudes de vie","agir":"Limiter la fréquence de certaines maladies génétiques","situation":"Lors d'une visite à l'hôpital Laquintinie, un médecin montre l'hémoglobine S d'un malade drépanocytaire.","tache":"Explique le lien entre gène et maladie."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r18",{"duree":20,"titre":"Structure du tissu nerveux","accroche":"Des milliards de cellules connectées.","intro":"Le tissu nerveux réunit les neurones et leurs cellules de soutien.","objectifs":["décrire un neurone","distinguer substance grise et blanche","préparer une dissection"],"parties":[{"t":"Le neurone","html":"<div class='def'><b>Définition</b>Le <strong>neurone</strong> est la cellule nerveuse. Il comprend un corps cellulaire, des dendrites et un axone.</div>"},{"t":"Substances grise et blanche","verrou":true},{"t":"Le nerf","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":18,"apc":{"module":"Neurones et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver les défenses de l'organisme","situation":"En TP à Bamenda, un groupe prépare la dissection de l'encéphale d'un petit mammifère.","tache":"Cite trois règles à respecter."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r19",{"duree":20,"titre":"Le potentiel d'action","accroche":"Tout ou rien : le neurone ne chuchote pas.","intro":"Une stimulation suffisante provoque une inversion brève du potentiel de membrane.","objectifs":["décrire le potentiel d'action","expliquer les mouvements d'ions","appliquer la loi du tout ou rien"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>potentiel d'action</strong> est une inversion brève et propagée de la polarité membranaire, déclenchée à partir d'un seuil.</div>"},{"t":"Les phases","verrou":true},{"t":"Propriétés","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":19,"apc":{"module":"Neurones et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver les défenses de l'organisme","situation":"Un élève de Mbalmayo augmente l'intensité d'un stimulus et croit que chaque potentiel d'action devient plus grand.","tache":"Corrige son idée."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r20",{"duree":20,"titre":"Propagation du potentiel d'action","accroche":"Jusqu'à plus de 100 m/s sur certaines fibres.","intro":"Le potentiel d'action se propage de proche en proche ou de nœud en nœud.","objectifs":["comparer les conductions","calculer une vitesse","expliquer le rôle de la myéline"],"parties":[{"t":"Les modes de conduction","html":"<div class='def'><b>Définition</b>Dans une fibre sans myéline, la conduction est <strong>de proche en proche</strong>. Dans une fibre myélinisée, elle est <strong>saltatoire</strong>, d'un nœud de Ranvier à l'autre.</div>"},{"t":"La vitesse","verrou":true},{"t":"La période réfractaire","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":20,"apc":{"module":"Neurones et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver les défenses de l'organisme","situation":"Un enregistrement à deux électrodes sépare de 4 cm un même potentiel d'action, avec un retard de 1 ms.","tache":"Calcule la vitesse."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r21",{"duree":20,"titre":"La synapse : fonctionnement","accroche":"Un message électrique devient chimique, puis redevient électrique.","intro":"La transmission synaptique met en jeu un neurotransmetteur.","objectifs":["décrire les étapes","expliquer le rôle du Ca²⁺","distinguer PPSE et PPSI"],"parties":[{"t":"Les étapes","html":"<div class='def'><b>Définition</b>La <strong>transmission synaptique</strong> : l'arrivée du potentiel d'action provoque l'entrée de Ca²⁺, l'exocytose du neurotransmetteur et sa fixation sur des récepteurs postsynaptiques.</div>"},{"t":"PPSE et PPSI","verrou":true},{"t":"Fin du message","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":21,"apc":{"module":"Neurones et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver les défenses de l'organisme","situation":"On stimule un neurone présynaptique et on enregistre : potentiel d'action présynaptique à t = 0 ; dépolarisation de la cellule postsynaptique à t = 0,5 ms. Sur une même fibre sans synapse, le message parcourt la même distance en 0,01 ms.","tache":"Explique ce délai."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r22",{"duree":20,"titre":"Intégration : drogues et message nerveux","accroche":"Un camarade propose un comprimé avant l'examen.","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation réelle, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","mobiliser les ressources","rédiger une réponse argumentée"],"parties":[{"t":"La notion à mobiliser","html":"<div class='def'><b>Définition</b>Une <strong>substance psychoactive</strong> modifie la transmission synaptique.</div>"},{"t":"Le plan de la réponse","verrou":true},{"t":"La production attendue","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":22,"apc":{"module":"Neurones et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver les défenses de l'organisme","situation":"Avant les examens à Bafia, un camarade propose un comprimé censé empêcher de dormir.","tache":"Rédige un conseil argumenté."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r23",{"duree":20,"titre":"Origine des cellules immunitaires et reconnaissance du non-soi","accroche":"Tout commence dans la moelle osseuse.","intro":"Les cellules immunitaires naissent dans la moelle osseuse et se répartissent dans l'organisme.","objectifs":["citer les cellules","préciser leur origine","réaliser un frottis"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Les <strong>leucocytes</strong> proviennent de cellules souches de la moelle osseuse.</div>"},{"t":"Maturation","html":"<p>Les lymphocytes B mûrissent dans la moelle osseuse, les lymphocytes T dans le thymus.</p>","retenir":"LT : thymus.","labo":{"type":"trier","invite":"Choisis une cellule.","items":[["Macrophage","phagocytose."],["Lymphocyte B","donne des plasmocytes."],["Lymphocyte T4","coordonne."],["Lymphocyte T8","détruit les cellules infectées."]]}},{"t":"Le soi et l'antigène","html":"<p>Le <strong>soi</strong> regroupe les molécules propres à l'individu. Un <strong>antigène</strong> est reconnu comme étranger. L'anticorps, en forme de Y, s'y fixe spécifiquement.</p>","retenir":"Un anticorps, un antigène."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Évaluation des savoirs (QCM).</strong> Les lymphocytes naissent dans :</p><ol type='a'><li>le cœur</li><li>la moelle osseuse</li><li>le foie adulte</li><li>la peau</li></ol><details><summary>Voir la réponse</summary><p><strong>la moelle osseuse</strong>. Ils dérivent de cellules souches hématopoïétiques.</p></details><p><strong>Évaluation des savoir-faire.</strong></p><p>Où mûrissent les lymphocytes T ?</p><details><summary>Voir la réponse</summary><p>(Réponse : dans le thymus.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Compétence visée.</strong> Comprendre et préserver les défenses de l'organisme.</p><p><strong>Situation.</strong> Le frottis sanguin d'un patient montre de nombreux granulocytes, quelques monocytes et des lymphocytes. Le laborantin explique que toutes ces cellules viennent du même endroit.</p><p><strong>Consigne 1.</strong> Indique l'organe où naissent les cellules immunitaires et ceux où mûrissent les lymphocytes B et T.</p><p><strong>Consigne 2.</strong> Explique comment l'organisme reconnaît le soi et le non-soi.</p><details><summary>Voir une réponse attendue</summary><p>Elles naissent dans la moelle osseuse rouge à partir de cellules souches ; les lymphocytes B y mûrissent, les lymphocytes T mûrissent dans le thymus. Le soi est défini par les marqueurs du CMH (HLA) présents sur les cellules ; les lymphocytes reconnaissent, grâce à leurs récepteurs, les antigènes étrangers (non-soi) ou un soi modifié.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans l'analyse."}],"revision":["Moelle osseuse.","Thymus.","Organes lymphoïdes."],"exo":"<p>Où mûrissent les lymphocytes T ? <em>(Réponse : dans le thymus.)</em></p>","quiz":[{"q":"Les lymphocytes naissent dans :","r":["le cœur","la moelle osseuse","le foie adulte","la peau"],"b":1,"e":"Ils dérivent de cellules souches hématopoïétiques."},{"q":"Les lymphocytes T mûrissent dans :","r":["la moelle","la rate","le thymus","l'intestin"],"b":2,"e":"T vient de thymus."},{"q":"Les lymphocytes B mûrissent dans :","r":["le thymus","les ganglions","le cerveau","la moelle osseuse"],"b":3,"e":"Ils y acquièrent leurs récepteurs."},{"q":"Le soi est caractérisé par :","r":["les molécules du CMH","les anticorps circulants","les microbes de la flore intestinale","le volume de sang"],"b":0,"e":"Elles sont propres à chaque individu."},{"q":"Les LT reconnaissent un antigène :","r":["libre dans le plasma, sans présentation","associé à une molécule du CMH","sans récepteur membranaire","dans le noyau de la cellule infectée"],"b":1,"e":"C'est la double reconnaissance."},{"q":"Les LB reconnaissent l'antigène :","r":["par les molécules du CMH","par phagocytose de l'antigène","par leurs anticorps membranaires","par des hormones sécrétées"],"b":2,"e":"Ils le reconnaissent sous forme native."},{"q":"Les organes lymphoïdes secondaires sont :","r":["la moelle et le thymus","le cœur et les reins","les os","les ganglions et la rate"],"b":3,"e":"C'est le lieu des réponses immunitaires."},{"q":"La cellule présentatrice de l'antigène est par exemple :","r":["un macrophage ou une cellule dendritique","un globule rouge qui transporte l'antigène","une plaquette fixée sur le microbe","un plasmocyte qui sécrète des anticorps"],"b":0,"e":"Elle présente des fragments d'antigène aux LT4."},{"q":"La sélection des lymphocytes non autoréactifs assure :","r":["la mémoire immunitaire","la tolérance du soi","la phagocytose","la vaccination"],"b":1,"e":"Les lymphocytes dangereux sont éliminés."},{"q":"Le non-soi modifié correspond par exemple à :","r":["un globule rouge sain de l'individu","un neurone sain","une cellule infectée par un virus","une hormone de l'organisme"],"b":2,"e":"Elle présente des peptides viraux."}],"c":"Tle C","m":"svt","rang":23,"apc":{"module":"Neurones et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver les défenses de l'organisme","situation":"Un laborantin de Limbé réalise un frottis sanguin pour un examen de routine.","tache":"Dis ce qu'il observera."},"gratuit":true});
VRT_L("tle-c-svt-r24",{"duree":20,"titre":"Réponse non spécifique et réponse à médiation cellulaire","accroche":"La première ligne de défense.","intro":"Elle agit rapidement contre une grande variété d'agents infectieux.","objectifs":["citer les barrières","décrire l'inflammation","décrire la phagocytose"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>réponse non spécifique</strong> s'exerce sans reconnaissance préalable d'un antigène particulier.</div>"},{"t":"La phagocytose","verrou":true},{"t":"La réponse à médiation cellulaire","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":24,"apc":{"module":"Neurones et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver les défenses de l'organisme","situation":"Une plaie au pied d'un agriculteur à Nkongsamba devient rouge et chaude.","tache":"Explique ces signes."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r25",{"duree":20,"titre":"Réponse à médiation humorale et mémoire immunitaire","accroche":"LT, LB, plasmocytes : chacun son rôle.","intro":"La réponse spécifique cible un antigène précis.","objectifs":["décrire les étapes","distinguer les deux réponses","expliquer la coopération"],"parties":[{"t":"La réponse humorale","html":"<div class='def'><b>Définition</b>La <strong>réponse humorale</strong> : les LB activés se transforment en plasmocytes qui sécrètent des anticorps circulants.</div>","retenir":"Plasmocytes : anticorps."},{"t":"La mémoire","verrou":true},{"t":"La vaccination","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":25,"apc":{"module":"Neurones et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver les défenses de l'organisme","situation":"Chez un patient vacciné contre le tétanos, on observe dans un ganglion des lymphocytes B qui grossissent, puis des cellules au cytoplasme rempli de réticulum endoplasmique granuleux ; le taux d'anticorps antitétaniques passe de 0,01 à 1 UI/mL.","tache":"Identifie cette cellule et son rôle."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r26",{"duree":20,"titre":"Maladies auto-immunes","accroche":"Quand le système se trompe de cible.","intro":"Dans certaines maladies, le système immunitaire attaque les constituants de l'organisme.","objectifs":["définir l'auto-immunité","donner des exemples","expliquer le traitement"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>maladie auto-immune</strong> résulte d'une réaction immunitaire dirigée contre le soi.</div>"},{"t":"Exemples","verrou":true},{"t":"Prise en charge","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":26,"apc":{"module":"Neurones et immunité","famille":"Recherche d'un meilleur équilibre de vie","agir":"Comprendre et préserver les défenses de l'organisme","situation":"Une jeune fille diabétique à Yaoundé apprend que sa maladie est auto-immune.","tache":"Explique ce terme."},"verrou":true,"nq":10,"labo":true});
